CREATE DATABASE schemadb; USE schemadb; CREATE TABLE companies ( company_id INT PRIMARY KEY AUTO_INCREMENT, company_name VARCHAR(100) UNIQUE, city VARCHAR(50) NOT NULL, industry VARCHAR(50) NOT NULL ); CREATE TABLE users ( user_id INT PRIMARY KEY AUTO_INCREMENT, company_id INT, full_name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE, role VARCHAR(50), is_active TINYINT, FOREIGN KEY (company_id) REFERENCES companies (company_id), CONSTRAINT chk_is_active CHECK(is_active IN (0,1)) ); CREATE TABLE plans ( plan_id INT PRIMARY KEY AUTO_INCREMENT, plan_name VARCHAR(100) NOT NULL UNIQUE, monthly_price DECIMAL(10,2), max_users INT, CONSTRAINT chk_monthly_price CHECK(monthly_price > 0), CONSTRAINT chk_max_users CHECK(max_users > 0) ); CREATE TABLE subscriptions ( subscription_id INT PRIMARY KEY AUTO_INCREMENT, company_id INT, plan_id INT, start_date DATE, status VARCHAR(50), FOREIGN KEY (company_id) REFERENCES companies(company_id), FOREIGN KEY (plan_id) REFERENCES plans(plan_id), CONSTRAINT chk_status CHECK(status IN ("active","paused","cancelled")) ); CREATE TABLE payments ( payment_id INT PRIMARY KEY AUTO_INCREMENT, subscription_id INT, payment_date DATE, amount INT, payment_status VARCHAR(50), CONSTRAINT chk_payment_status CHECK(payment_status IN ('paid','pending','failed')), CONSTRAINT chk_amount CHECK(amount > 0), FOREIGN KEY (subscription_id) REFERENCES subscriptions(subscription_id) ); CREATE TABLE support_tickets ( ticket_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, issue_type VARCHAR(100) NOT NULL, priority VARCHAR(10) NOT NULL, status VARCHAR(15) NOT NULL, created_date DATE NOT NULL DEFAULT (CURRENT_DATE), CONSTRAINT fk_support_tickets_users FOREIGN KEY (user_id) REFERENCES users(user_id), CONSTRAINT chk_ticket_priority CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')), CONSTRAINT chk_ticket_status CHECK (status IN ('Open', 'In Progress', 'Resolved', 'Closed')) );